(()=>{'use strict';const form=document.getElementById('feedback-form');if(!form)return;
const $=id=>document.getElementById(id),field=n=>form.elements.namedItem(n),draftKey='gtav-feedback-draft-v1';let step=0,busy=false,frame=0,started=0,activePointer=null,toastTimer=0;
const placeHelper=()=>{const launcher=document.querySelector('.ask-franklin-launcher'),slot=$('feedback-helper-slot');if(launcher&&slot){slot.append(launcher);return true}return false};if(!placeHelper()){const observer=new MutationObserver(()=>{if(placeHelper())observer.disconnect()});observer.observe(document.body,{childList:true,subtree:true})}
const id=()=>crypto.randomUUID?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16));let reportId=id();
const toast=message=>{$('feedback-toast').textContent=message;$('feedback-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('feedback-toast').hidden=true,6500)};
const data=()=>({id:reportId,...Object.fromEntries(new FormData(form)),rating:Number(field('rating').value),version:field('version').value.replace(/,/g,'.')});
function save(){try{localStorage.setItem(draftKey,JSON.stringify(data()));$('draft-state').textContent='Draft saved on this device'}catch{$('draft-state').textContent='Draft kept until you leave this page'}}
function update(){const d=data();$('issue-fields').hidden=d.kind!=='issue';$('message-label').textContent=d.kind==='issue'?'What happened, and what did you expect?':'Your experience';field('message').placeholder=d.kind==='issue'?'Describe the problem and what should have happened.':'What worked well, or what would make it better?';$('message-count').textContent=field('message').value.length;document.querySelectorAll('.star-picker label').forEach((l,i)=>l.toggleAttribute('data-filled',i<d.rating));$('rating-caption').textContent=['Select 1–5 stars','Very poor','Needs work','Okay','Good','Excellent'][d.rating]||'Select 1–5 stars'}
function valid(){if(step===0&&!field('target').value){toast('Choose Franklin helper or the GTA V iOS launcher.');return false}if(step===1){if(!field('rating').value){toast('Please select a star rating.');return false}for(const [name,min,message]of[['title',5,'Add a short summary with at least 5 characters.'],['message',15,'Tell us a little more, using at least 15 characters.'],...(field('kind').value==='issue'?[['steps',10,'Add the steps that caused the issue, using at least 10 characters.']]:[])]){if(field(name).value.trim().length<min){toast(message);field(name).focus();return false}}}return true}
function review(){const d=data(),box=$('feedback-review');box.replaceChildren();const header=document.createElement('div');header.className='review-header';for(const text of[d.target==='helper'?'Franklin helper':'GTA V iOS launcher',d.kind==='issue'?'Issue report':'Feedback','★'.repeat(d.rating)+'☆'.repeat(5-d.rating)]){const s=document.createElement('span');s.textContent=text;if(text.includes('★'))s.className='review-stars';header.append(s)}box.append(header);const h=document.createElement('h3');h.textContent=d.title;box.append(h);for(const text of[d.message,...(d.kind==='issue'?['Steps to reproduce:\n'+d.steps,[d.os,d.version,d.device,d.build].filter(Boolean).join(' · ')]:[])]){const p=document.createElement('p');p.textContent=text;box.append(p)}}
function show(n,focus=true){step=n;document.querySelectorAll('.feedback-step').forEach((s,i)=>s.hidden=i!==n);document.querySelectorAll('.feedback-steps li').forEach((s,i)=>{if(i===n)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current')});if(n===2)review();if(focus){const h=document.querySelector(`.feedback-step[data-step="${n}"] h2`);h?.focus({preventScroll:true});document.querySelector('.feedback-sheet').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}}
try{const saved=JSON.parse(localStorage.getItem(draftKey)||'null');if(saved&&typeof saved==='object'){for(const name of['target','kind','rating','title','message','steps','os','version','build','device']){if(saved[name]!=null)field(name).value=String(saved[name]).slice(0,name==='message'?3000:name==='steps'?2000:100)}if(/^[0-9a-f-]{36}$/i.test(saved.id))reportId=saved.id}else{const profile=JSON.parse(localStorage.getItem('franklin-device-profile-v1')||'null');if(profile){field('os').value=profile.family||profile.os||'';field('version').value=profile.version||profile.osVersion||''}}}catch{}
update();form.addEventListener('input',()=>{update();save()});form.addEventListener('change',()=>{update();save()});form.addEventListener('submit',e=>e.preventDefault());document.querySelectorAll('.feedback-next').forEach(b=>{if(b.id!=='new-report')b.addEventListener('click',()=>{if(valid())show(step+1)})});document.querySelectorAll('.feedback-back').forEach(b=>b.addEventListener('click',()=>show(step-1)));
const hold=$('feedback-hold'),copy=$('hold-copy');$('feedback-consent').addEventListener('change',()=>{cancel();hold.disabled=!$('feedback-consent').checked||busy});
function cancel(){cancelAnimationFrame(frame);frame=0;started=0;activePointer=null;hold.style.setProperty('--hold','0');if(!busy)copy.textContent='Hold to send'}
async function send(){cancel();busy=true;hold.disabled=true;copy.textContent='Sending…';try{const response=await fetch('/api/feedback',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data())});let result;try{result=await response.json()}catch{throw Error('Feedback service is unavailable. Your draft is safe. Please try again later.')}if(!response.ok||!result.ok)throw Error(result.error||'The report could not be saved. Please try again.');form.hidden=true;$('feedback-success').hidden=false;$('copy-reference').textContent=result.reference;$('draft-state').textContent='Saved to the project inbox';try{localStorage.removeItem(draftKey)}catch{}window.dispatchEvent(new Event('community-rating-updated'));$('feedback-success').scrollIntoView({behavior:'smooth',block:'center'})}catch(e){toast(e.message==='Failed to fetch'?'Connection interrupted. Your draft is safe. Please try again.':e.message);copy.textContent='Hold to retry'}finally{busy=false;hold.disabled=!$('feedback-consent').checked}}
function start(){if(busy||hold.disabled||started)return;started=performance.now();copy.textContent='Keep holding…';function tick(now){const progress=Math.min(1,(now-started)/1200);hold.style.setProperty('--hold',String(progress));copy.textContent=progress<1?`Keep holding · ${Math.floor(progress*100)}%`:'Sending…';if(progress>=1){send();return}frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)}
hold.addEventListener('pointerdown',e=>{if(e.button!==0||hold.disabled)return;e.preventDefault();hold.setPointerCapture(e.pointerId);activePointer=e.pointerId;start()});hold.addEventListener('pointermove',e=>{if(e.pointerId!==activePointer)return;const r=hold.getBoundingClientRect();if(e.clientX<r.left-10||e.clientX>r.right+10||e.clientY<r.top-10||e.clientY>r.bottom+10)cancel()});for(const event of['pointerup','pointercancel','lostpointercapture','blur'])hold.addEventListener(event,cancel);hold.addEventListener('contextmenu',e=>e.preventDefault());hold.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)start()}});hold.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();cancel()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel()});window.addEventListener('pagehide',cancel);
$('copy-reference').onclick=async()=>{try{await navigator.clipboard.writeText($('copy-reference').textContent);toast('Reference copied.')}catch{toast('Your reference: '+$('copy-reference').textContent)}};
$('new-report').onclick=()=>{form.reset();reportId=id();form.hidden=false;$('feedback-success').hidden=true;$('feedback-consent').checked=false;hold.disabled=true;copy.textContent='Hold to send';update();save();show(0)};
})();
